def dedupe(items):
    seen = set()
    for item in items:
        if item not in seen:
            seen.add(item)
            yield item

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals based on the start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # If the current interval overlaps with the last interval, merge them
            last[1] = max(last[1], current[1])
        else:
            # If there's no overlap, add the current interval to the merged list
            merged.append(current)

    return merged

def binary_search(values, target):
    left, right = 0, len(values) - 1
    while left <= right:
        mid = (left + right) // 2
        if values[mid] == target:
            return mid
        elif values[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def count_words(text):
    import re
    words = re.findall(r'\b\w+\b', text.lower())
    return dict((word, words.count(word)) for word in words)

def chunked(items, size):
    if size <= 0:
        raise ValueError("Size must be greater than 0.")
    return [items[i:i+size] for i in range(0, len(items), size)]

def balanced_parens(text):
    stack = []
    for char in text:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or (char == ')' and stack[-1] != '(') or (char == ']' and stack[-1] != '[') or (char == '}' and stack[-1] != '{'):
                return False
            stack.pop()
    return len(stack) == 0
